#include "global_field.hpp"
#include <iostream>
using namespace rf;using namespace rf::experimental_projective;
// File staging is streamed; no second mesh/JSON/string allocation. A partial
// directory on I/O failure is explicitly NOT a success receipt.
struct Out {
 FILE* f{};explicit Out(const std::filesystem::path& p){auto parent=trace_test::parentDirectory(p);int fd=::openat(parent.value,p.filename().c_str(),O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW|O_CLOEXEC,0600);require(fd>=0,"output must be fresh");f=::fdopen(fd,"w");if(!f){::close(fd);throw Error("fdopen");}}
 void close(){require(f&&std::fflush(f)==0&&!std::ferror(f)&&::fsync(::fileno(f))==0,"output flush");int rc=std::fclose(f);f=nullptr;require(rc==0,"output close");}~Out(){if(f)std::fclose(f);}
};
int main(int argc,char** argv){try{
 require(argc==4,"usage: replay ABS_INPUT DEPTH_ID FRESH_ABS_OUTPUT_DIR");
 auto s=trace_test::readSnapshot(argv[1],argv[2]);Builder b(s);b.run();auto& w=*b.w;
 trace_test::freshDirectory(argv[3]);std::filesystem::path dir=argv[3];
 {Out out(dir/"experimental.ply");auto* f=out.f;std::fprintf(f,"ply\nformat ascii 1.0\ncomment EXPERIMENTAL canonical_projective_camera_z_field_v1 NOT verified sample vertices\nelement vertex %u\nproperty double x\nproperty double y\nproperty double z\nelement face %u\nproperty list uchar uint vertex_indices\nend_header\n",w.verticesN,w.facesN);for(unsigned i=0;i<w.verticesN;i++){auto p=w.vertices[i];std::fprintf(f,"%.17g %.17g %.17g\n",p.x,p.y,p.z);}for(unsigned i=0;i<w.facesN;i++){auto t=w.faces[i];std::fprintf(f,"3 %u %u %u\n",t.vertex[0],t.vertex[1],t.vertex[2]);}out.close();}
 {Out out(dir/"provenance.json");auto* f=out.f;std::fprintf(f,"{\"representation\":\"experimental_canonical_projective_camera_z_field_v1\",\"depthIdentity\":\"%s\",\"pitch\":%.17g,\"truncation\":%.17g,\"wholeFaceSlab\":%.17g,\"workspaceBytes\":%zu,\"stackAllowanceBytes\":65536,\"operations\":%llu,\"nodes\":%u,\"cells\":%u,\"rejectedFaces\":%llu,\"vertices\":%u,\"faces\":%u,\"boundaryEdges\":%llu,\"nonmanifoldEdges\":%llu,\"windingConflictEdges\":%llu,\"observedPatches\":[",s.depthIdentity.c_str(),w.pitch,w.tau,w.pitch*.25,sizeof(Workspace),(unsigned long long)w.operations,w.nodesN,w.cellsN,(unsigned long long)w.rejectedFaces,w.verticesN,w.facesN,(unsigned long long)w.boundaryEdges,(unsigned long long)w.nonmanifoldEdges,(unsigned long long)w.windingConflictEdges);for(unsigned i=0;i<w.patchesN;i++){auto p=w.patches[i];std::fprintf(f,"%s[%u,%u,%u,%u]",i?",":"",unsigned(p.camera),p.source[0],p.source[1],p.source[2]);}std::fprintf(f,"],\"faceWitnessPatch\":[");for(unsigned i=0;i<w.facesN;i++)std::fprintf(f,"%s%u",i?",":"",w.faces[i].witness);std::fprintf(f,"]}\n");out.close();}
 {Out out(dir/"counters.json");const auto& c=w.counters;std::fprintf(out.f,"{\"scope\":\"new_projective_algorithm_only_not_v4_attribution\",\"allocationVisits\":%llu,\"existingNodeVisits\":%llu,\"noNearBandVisits\":%llu,\"cameraUnknown\":%llu,\"cameraBehind\":%llu,\"cameraNear\":%llu,\"cameraFront\":%llu,\"mixedSignNodes\":%llu,\"missingCornerCells\":%llu,\"validCells\":%llu,\"allOneSignTetra\":%llu,\"crossingTetra\":%llu,\"faceCandidates\":%llu,\"areaRejected\":%llu,\"witnessRejected\":%llu,\"acceptedFaces\":%u}\n",(unsigned long long)c.allocationVisits,(unsigned long long)c.existingNodeVisits,(unsigned long long)c.noNearBandVisits,(unsigned long long)c.cameraUnknown,(unsigned long long)c.cameraBehind,(unsigned long long)c.cameraNear,(unsigned long long)c.cameraFront,(unsigned long long)c.mixedSignNodes,(unsigned long long)c.missingCornerCells,(unsigned long long)c.validCells,(unsigned long long)c.allOneSignTetra,(unsigned long long)c.crossingTetra,(unsigned long long)c.faceCandidates,(unsigned long long)c.areaRejected,(unsigned long long)c.witnessRejected,w.facesN);out.close();}
 {Out out(dir/"SUCCESS");std::fprintf(out.f,"experimental-only; not a quality or production acceptance\n");out.close();}
 std::cout<<"experimental replay finished; vertices="<<w.verticesN<<" faces="<<w.facesN<<" scratch="<<sizeof(Workspace)+65536<<'\n';return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL CLOSED: "<<e.what()<<'\n';return 1;}}
